package com.freightconnect.ui.fragments

import android.os.Bundle
import android.view.*
import androidx.fragment.app.Fragment
import androidx.fragment.app.viewModels
import androidx.navigation.fragment.findNavController
import androidx.recyclerview.widget.LinearLayoutManager
import com.freightconnect.R
import com.freightconnect.databinding.FragmentBusinessHomeBinding
import com.freightconnect.ui.adapters.CargoAdapter
import com.freightconnect.viewmodel.BusinessHomeViewModel

class BusinessHomeFragment : Fragment() {

    private var _binding: FragmentBusinessHomeBinding? = null
    private val binding get() = _binding!!
    private val viewModel: BusinessHomeViewModel by viewModels()
    private lateinit var cargoAdapter: CargoAdapter

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        _binding = FragmentBusinessHomeBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        setupRecyclerView()
        setupFab()
        observeData()
    }

    override fun onResume() {
        super.onResume()
        viewModel.refreshData()
    }

    private fun setupRecyclerView() {
        cargoAdapter = CargoAdapter(
            onCargoClick = { cargo ->
                val action = BusinessHomeFragmentDirections.actionHomeToCargoDetail(cargo.cargoId)
                findNavController().navigate(action)
            }
        )

        binding.rvCargos.apply {
            adapter = cargoAdapter
            layoutManager = LinearLayoutManager(requireContext())
        }

        binding.swipeRefresh.setOnRefreshListener {
            viewModel.refreshData()
        }
    }

    /**
     * Setup FAB to post new cargo
     */
    private fun setupFab() {
        binding.fabPostCargo.setOnClickListener {
            findNavController().navigate(R.id.action_home_to_postCargo)
        }
    }

    /**
     * Observe dashboard data and update UI accordingly
     */
    private fun observeData() {
        viewModel.myCargos.observe(viewLifecycleOwner) { cargos ->
            binding.swipeRefresh.isRefreshing = false

            if (cargos.isEmpty()) {
                binding.layoutEmpty.visibility = View.VISIBLE
                binding.rvCargos.visibility = View.GONE
                binding.tvEmptyMessage.text = getString(R.string.no_cargo_posted)
            } else {
                binding.layoutEmpty.visibility = View.GONE
                binding.rvCargos.visibility = View.VISIBLE
                cargoAdapter.submitList(cargos)
            }
        }

        viewModel.receivedInterests.observe(viewLifecycleOwner) { interests ->
            if (interests.isNotEmpty()) {
                binding.badgeInterests.visibility = View.VISIBLE
                binding.badgeInterests.text = interests.size.toString()
            } else {
                binding.badgeInterests.visibility = View.GONE
            }
        }

        viewModel.isLoading.observe(viewLifecycleOwner) { loading ->
            if (loading) {
                binding.shimmerLayout.visibility = View.VISIBLE
                binding.shimmerLayout.startShimmer()
                binding.rvCargos.visibility = View.GONE
            } else {
                binding.shimmerLayout.stopShimmer()
                binding.shimmerLayout.visibility = View.GONE
            }
        }

        // Update dashboard metrics
        updateDashboardMetrics()
    }

    /**
     * Update dashboard metric cards
     */
    private fun updateDashboardMetrics() {
        val tvTotalCargos = binding.root.findViewById<android.widget.TextView>(R.id.tvTotalCargos)
        val tvOpenCargos = binding.root.findViewById<android.widget.TextView>(R.id.tvOpenCargos)
        val tvPendingCargos = binding.root.findViewById<android.widget.TextView>(R.id.tvPendingCargos)
        val tvBookedCargos = binding.root.findViewById<android.widget.TextView>(R.id.tvBookedCargos)

        viewModel.totalCargos.observe(viewLifecycleOwner) { count ->
            tvTotalCargos?.text = count.toString()
        }

        viewModel.openCargos.observe(viewLifecycleOwner) { count ->
            tvOpenCargos?.text = count.toString()
        }

        viewModel.pendingCargos.observe(viewLifecycleOwner) { count ->
            tvPendingCargos?.text = count.toString()
        }

        viewModel.bookedCargos.observe(viewLifecycleOwner) { count ->
            tvBookedCargos?.text = count.toString()
        }
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.freightconnect.ui.fragments

import android.os.Bundle
import android.view.*
import androidx.fragment.app.Fragment
import androidx.fragment.app.activityViewModels
import androidx.fragment.app.viewModels
import androidx.navigation.fragment.findNavController
import androidx.recyclerview.widget.LinearLayoutManager
import com.freightconnect.R
import com.freightconnect.databinding.FragmentBusinessHomeBinding
import com.freightconnect.ui.adapters.CargoAdapter
import com.freightconnect.viewmodel.BusinessHomeViewModel
import com.freightconnect.viewmodel.MainViewModel
import com.google.android.material.dialog.MaterialAlertDialogBuilder

class BusinessHomeFragment : Fragment() {

    private var _binding: FragmentBusinessHomeBinding? = null
    private val binding get() = _binding!!
    private val viewModel: BusinessHomeViewModel by viewModels()
    private val mainViewModel: MainViewModel by activityViewModels()
    private lateinit var cargoAdapter: CargoAdapter

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        _binding = FragmentBusinessHomeBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        setupToolbar()
        setupRecyclerView()
        setupFab()
        observeData()
    }

    override fun onResume() {
        super.onResume()
        viewModel.refreshData()
    }

    private fun setupRecyclerView() {
        cargoAdapter = CargoAdapter(
            onCargoClick = { cargo ->
                val action = BusinessHomeFragmentDirections.actionHomeToCargoDetail(cargo.cargoId)
                findNavController().navigate(action)
            }
        )

        binding.rvCargos.apply {
            adapter = cargoAdapter
            layoutManager = LinearLayoutManager(requireContext())
        }

        binding.swipeRefresh.setOnRefreshListener {
            viewModel.refreshData()
        }
    }

    /**
     * Setup FAB to post new cargo
     */
    private fun setupFab() {
        binding.fabPostCargo.setOnClickListener {
            findNavController().navigate(R.id.action_home_to_postCargo)
        }
    }

    /**
     * Observe dashboard data and update UI accordingly
     */
    private fun observeData() {
        viewModel.myCargos.observe(viewLifecycleOwner) { cargos ->
            binding.swipeRefresh.isRefreshing = false

            if (cargos.isEmpty()) {
                binding.layoutEmpty.visibility = View.VISIBLE
                binding.rvCargos.visibility = View.GONE
                binding.tvEmptyMessage.text = getString(R.string.no_cargo_posted)
            } else {
                binding.layoutEmpty.visibility = View.GONE
                binding.rvCargos.visibility = View.VISIBLE
                cargoAdapter.submitList(cargos)
            }
        }

        viewModel.receivedInterests.observe(viewLifecycleOwner) { interests ->
            if (interests.isNotEmpty()) {
                binding.badgeInterests.visibility = View.VISIBLE
                binding.badgeInterests.text = interests.size.toString()
            } else {
                binding.badgeInterests.visibility = View.GONE
            }
        }

        viewModel.isLoading.observe(viewLifecycleOwner) { loading ->
            if (loading) {
                binding.shimmerLayout.visibility = View.VISIBLE
                binding.shimmerLayout.startShimmer()
                binding.rvCargos.visibility = View.GONE
            } else {
                binding.shimmerLayout.stopShimmer()
                binding.shimmerLayout.visibility = View.GONE
            }
        }

        // Update dashboard metrics
        updateDashboardMetrics()
    }

    /**
     * Update dashboard metric cards
     */
    private fun updateDashboardMetrics() {
        val tvTotalCargos = binding.root.findViewById<android.widget.TextView>(R.id.tvTotalCargos)
        val tvOpenCargos = binding.root.findViewById<android.widget.TextView>(R.id.tvOpenCargos)
        val tvPendingCargos = binding.root.findViewById<android.widget.TextView>(R.id.tvPendingCargos)
        val tvBookedCargos = binding.root.findViewById<android.widget.TextView>(R.id.tvBookedCargos)

        viewModel.totalCargos.observe(viewLifecycleOwner) { count ->
            tvTotalCargos?.text = count.toString()
        }

        viewModel.openCargos.observe(viewLifecycleOwner) { count ->
            tvOpenCargos?.text = count.toString()
        }

        viewModel.pendingCargos.observe(viewLifecycleOwner) { count ->
            tvPendingCargos?.text = count.toString()
        }

        viewModel.bookedCargos.observe(viewLifecycleOwner) { count ->
            tvBookedCargos?.text = count.toString()
        }
    }

    private fun setupToolbar() {
        mainViewModel.currentUser.observe(viewLifecycleOwner) { user ->
            val name = user?.name?.trim().orEmpty()
            val title = if (name.isNotEmpty()) {
                getString(R.string.greeting_format, name)
            } else {
                getString(R.string.greeting_fallback)
            }
            binding.toolbar.title = title
        }

        binding.toolbar.setOnMenuItemClickListener { item ->
            if (item.itemId == R.id.action_help) {
                showHelpDialog()
                true
            } else {
                false
            }
        }
    }

    private fun showHelpDialog() {
        val phone = getString(R.string.support_phone_value)
        val email = getString(R.string.support_email_value)
        val message = getString(R.string.support_message, phone, email)

        MaterialAlertDialogBuilder(requireContext())
            .setTitle(R.string.support_title)
            .setMessage(message)
            .setPositiveButton(R.string.ok, null)
            .show()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.freightconnect.ui.adapters
import android.view.LayoutInflater
import android.view.ViewGroup
import androidx.recyclerview.widget.DiffUtil
import androidx.recyclerview.widget.ListAdapter
import androidx.recyclerview.widget.RecyclerView
import com.freightconnect.R
import com.freightconnect.databinding.ItemCargoCardBinding
import com.freightconnect.model.CargoRequest
import com.freightconnect.model.CargoStatus
import java.text.SimpleDateFormat
import java.util.*

/**
 * CargoAdapter - Display list of cargo requests
 *
 * Used in:
 * - BusinessHomeFragment (my posted cargo)
 * - SearchCargosFragment (browse available cargo for fleet owners)
 *
 * Click handling: Delegates to onCargoClick callback for navigation to detail screen
 */
class CargoAdapter(
    private val onCargoClick: (CargoRequest) -> Unit
) : ListAdapter<CargoRequest, CargoAdapter.CargoViewHolder>(CargoDiffCallback()) {

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): CargoViewHolder {
        val binding = ItemCargoCardBinding.inflate(
            LayoutInflater.from(parent.context), parent, false
        )
        return CargoViewHolder(binding)
    }

    override fun onBindViewHolder(holder: CargoViewHolder, position: Int) {
        holder.bind(getItem(position))
    }

    inner class CargoViewHolder(
        private val binding: ItemCargoCardBinding
    ) : RecyclerView.ViewHolder(binding.root) {

        fun bind(cargo: CargoRequest) {
            binding.apply {
                tvGoodsType.text = cargo.goodsType.displayNameEn
                tvPickupCity.text = cargo.pickupCity
                tvDeliveryCity.text = cargo.deliveryCity
                tvWeight.text = "${cargo.weightTons} tons"
                tvBudget.text = "₹${cargo.budgetAmount.toLong()}"
                tvPickupDate.text = SimpleDateFormat("dd MMM", Locale.getDefault())
                    .format(Date(cargo.pickupDate))
                tvBusinessOwner.text = cargo.businessOwnerName

                // Status badge with color-coded display
                val (statusColor, statusText) = when (cargo.status) {
                    CargoStatus.OPEN -> Pair(R.color.status_open, "Open")
                    CargoStatus.PENDING -> Pair(R.color.status_pending, "Pending")
                    CargoStatus.BOOKED -> Pair(R.color.status_booked, "Booked")
                    CargoStatus.IN_TRANSIT -> Pair(R.color.status_in_transit, "In Transit")
                    CargoStatus.DELIVERED -> Pair(R.color.status_completed, "Delivered")
                    CargoStatus.CANCELLED -> Pair(R.color.status_cancelled, "Cancelled")
                }
                tvStatus.text = statusText
                tvStatus.setBackgroundResource(statusColor)

                // Navigate to cargo details on click
                root.setOnClickListener { onCargoClick(cargo) }
            }
        }
    }

    private class CargoDiffCallback : DiffUtil.ItemCallback<CargoRequest>() {
        override fun areItemsTheSame(oldItem: CargoRequest, newItem: CargoRequest) =
            oldItem.cargoId == newItem.cargoId

        override fun areContentsTheSame(oldItem: CargoRequest, newItem: CargoRequest) =
            oldItem == newItem
    }
}

package com.freightconnect.ui.adapters
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.core.content.ContextCompat
import androidx.recyclerview.widget.DiffUtil
import androidx.recyclerview.widget.ListAdapter
import androidx.recyclerview.widget.RecyclerView
import com.freightconnect.R
import com.freightconnect.databinding.ItemCargoCardBinding
import com.freightconnect.model.CargoRequest
import com.freightconnect.model.CargoStatus
import java.text.SimpleDateFormat
import java.util.*

/**
 * CargoAdapter - Display list of cargo requests
 *
 * Used in:
 * - BusinessHomeFragment (my posted cargo)
 * - SearchCargosFragment (browse available cargo for fleet owners)
 *
 * Click handling: Delegates to onCargoClick callback for navigation to detail screen
 */
class CargoAdapter(
    private val onCargoClick: (CargoRequest) -> Unit
) : ListAdapter<CargoRequest, CargoAdapter.CargoViewHolder>(CargoDiffCallback()) {

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): CargoViewHolder {
        val binding = ItemCargoCardBinding.inflate(
            LayoutInflater.from(parent.context), parent, false
        )
        return CargoViewHolder(binding)
    }

    override fun onBindViewHolder(holder: CargoViewHolder, position: Int) {
        holder.bind(getItem(position))
    }

    inner class CargoViewHolder(
        private val binding: ItemCargoCardBinding
    ) : RecyclerView.ViewHolder(binding.root) {

        fun bind(cargo: CargoRequest) {
            binding.apply {
                tvGoodsType.text = cargo.goodsType.displayNameEn
                tvPickupCity.text = cargo.pickupCity
                tvDeliveryCity.text = cargo.deliveryCity
                tvWeight.text = "${cargo.weightTons} tons"
                tvBudget.text = "₹${cargo.budgetAmount.toLong()}"
                tvPickupDate.text = SimpleDateFormat("dd MMM", Locale.getDefault())
                    .format(Date(cargo.pickupDate))
                tvBusinessOwner.text = cargo.businessOwnerName

                // Status badge with color-coded display
                val (statusColor, statusText) = when (cargo.status) {
                    CargoStatus.OPEN -> Pair(R.color.status_open, "Open")
                    CargoStatus.PENDING -> Pair(R.color.status_pending, "Pending")
                    CargoStatus.BOOKED -> Pair(R.color.status_booked, "Booked")
                    CargoStatus.IN_TRANSIT -> Pair(R.color.status_in_transit, "In Transit")
                    CargoStatus.DELIVERED -> Pair(R.color.status_completed, "Delivered")
                    CargoStatus.CANCELLED -> Pair(R.color.status_cancelled, "Cancelled")
                }
                tvStatus.text = statusText
                tvStatus.setBackgroundResource(statusColor)

                // Task 8: Add availability badge (green checkmark for available, red lock for matched)
                val isAvailable = cargo.status == CargoStatus.OPEN || cargo.status == CargoStatus.PENDING
                val (availIcon, availText, availColor) = if (isAvailable) {
                    Triple(R.drawable.ic_check_circle, root.context.getString(R.string.available), R.color.color_success)
                } else {
                    Triple(R.drawable.ic_close, root.context.getString(R.string.already_matched), R.color.color_error)
                }

                ivAvailability.setImageResource(availIcon)
                ivAvailability.setColorFilter(ContextCompat.getColor(root.context, availColor), android.graphics.PorterDuff.Mode.SRC_IN)
                tvAvailability.text = availText
                tvAvailability.setTextColor(ContextCompat.getColor(root.context, availColor))

                // Navigate to cargo details on click
                root.setOnClickListener { onCargoClick(cargo) }
            }
        }
    }

    private class CargoDiffCallback : DiffUtil.ItemCallback<CargoRequest>() {
        override fun areItemsTheSame(oldItem: CargoRequest, newItem: CargoRequest) =
            oldItem.cargoId == newItem.cargoId

        override fun areContentsTheSame(oldItem: CargoRequest, newItem: CargoRequest) =
            oldItem == newItem
    }
}

package com.freightconnect.ui.fragments

import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.view.*
import androidx.fragment.app.Fragment
import androidx.lifecycle.lifecycleScope
import androidx.navigation.fragment.navArgs
import com.freightconnect.R
import com.freightconnect.databinding.FragmentCargoDetailBinding
import com.freightconnect.model.BookingInterest
import com.freightconnect.model.UserRole
import com.freightconnect.repository.FreightRepository
import com.google.android.material.dialog.MaterialAlertDialogBuilder
import com.google.android.material.snackbar.Snackbar
import kotlinx.coroutines.launch
import java.text.SimpleDateFormat
import java.util.*

class CargoDetailFragment : Fragment() {

    private var _binding: FragmentCargoDetailBinding? = null
    private val binding get() = _binding!!
    private val args: CargoDetailFragmentArgs by navArgs()
    private val repo = FreightRepository()

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        _binding = FragmentCargoDetailBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        loadCargoDetails()
    }

    private fun loadCargoDetails() {
        lifecycleScope.launch {
            try {
                val cargo = repo.getCargoRequest(args.cargoId)
                val currentUser = repo.getUser(repo.currentUid())

                if (cargo == null) {
                    showSnackbar(getString(R.string.error_loading))
                    return@launch
                }

                binding.apply {
                    tvGoodsType.text = cargo.goodsType.displayNameEn
                    tvDescription.text = cargo.goodsDescription
                    tvWeight.text = "${cargo.weightTons} ${getString(R.string.tons)}"
                    tvPickupCity.text = cargo.pickupCity
                    tvDeliveryCity.text = cargo.deliveryCity
                    tvPickupAddress.text = cargo.pickupAddress
                    tvDeliveryAddress.text = cargo.deliveryAddress
                    tvRequiredVehicle.text = cargo.requiredVehicleType.displayNameEn
                    tvPickupDate.text = SimpleDateFormat("dd MMM yyyy", Locale.getDefault())
                        .format(Date(cargo.pickupDate))
                    tvBudget.text = "₹${cargo.budgetAmount.toLong()}"
                    tvStatus.text = cargo.status.name
                    tvSpecialReq.text = cargo.specialRequirements.ifBlank { "None" }
                    tvBusinessOwner.text = cargo.businessOwnerName
                    tvBusinessCompany.text = cargo.businessOwnerCompany
                }

                // Show actions based on user role
                when (currentUser?.role) {
                    UserRole.FLEET_OWNER -> {
                        binding.btnSendInterest.visibility = View.VISIBLE
                        binding.btnSendInterest.setOnClickListener {
                            showSendInterestDialog(cargo.cargoId)
                        }
                    }
                    UserRole.BUSINESS_OWNER -> {
                        if (cargo.businessOwnerUid == currentUser.uid && cargo.assignedFleetOwnerUid.isNotBlank()) {
                            binding.btnCall.visibility = View.VISIBLE
                            binding.btnCall.setOnClickListener {
                                dialPhone(cargo.businessOwnerPhone)
                            }
                        }
                    }
                    else -> {}
                }

            } catch (e: Exception) {
                showSnackbar(getString(R.string.error_loading))
            }
        }
    }

    private fun showSendInterestDialog(cargoId: String) {
        val dialogView = layoutInflater.inflate(R.layout.dialog_send_interest, null)
        val etMessage = dialogView.findViewById<com.google.android.material.textfield.TextInputEditText>(R.id.etMessage)
        val etOfferedPrice = dialogView.findViewById<com.google.android.material.textfield.TextInputEditText>(R.id.etOfferedPrice)

        MaterialAlertDialogBuilder(requireContext())
            .setTitle(R.string.send_interest_title)
            .setView(dialogView)
            .setPositiveButton(R.string.send_interest) { _, _ ->
                val message = etMessage.text.toString()
                val price = etOfferedPrice.text.toString().toDoubleOrNull() ?: 0.0
                sendInterest(cargoId, message, price)
            }
            .setNegativeButton(R.string.cancel, null)
            .show()
    }

    private fun sendInterest(cargoId: String, message: String, offeredPrice: Double) {
        lifecycleScope.launch {
            try {
                val currentUser = repo.getUser(repo.currentUid())
                val cargo = repo.getCargoRequest(cargoId)

                if (currentUser == null || cargo == null) return@launch

                val interest = BookingInterest(
                    initiatorUid = currentUser.uid,
                    initiatorName = currentUser.name,
                    initiatorPhone = currentUser.phone,
                    initiatorRole = UserRole.FLEET_OWNER,
                    targetUid = cargo.businessOwnerUid,
                    targetName = cargo.businessOwnerName,
                    targetRole = UserRole.BUSINESS_OWNER,
                    cargoId = cargoId,
                    message = message,
                    offeredPrice = offeredPrice
                )

                repo.sendInterest(interest)
                showSnackbar(getString(R.string.interest_sent))
            } catch (e: Exception) {
                showSnackbar(e.message ?: getString(R.string.error_loading))
            }
        }
    }

    private fun dialPhone(phone: String) {
        startActivity(Intent(Intent.ACTION_DIAL, Uri.parse("tel:$phone")))
    }

    private fun showSnackbar(msg: String) {
        Snackbar.make(binding.root, msg, Snackbar.LENGTH_LONG).show()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

