            }
            .setNegativeButton(R.string.cancel, null)
            .show()
    }

    private fun sendInterest(cargoId: String, message: String, offeredPrice: Double) {
        lifecycleScope.launch {
            try {
                val currentUser = repo.getUser(repo.currentUid())
                val cargo = repo.getCargoRequest(cargoId)

                if (currentUser == null || cargo == null) return@launch

                val interest = BookingInterest(
                    initiatorUid = currentUser.uid,
                    initiatorName = currentUser.name,
                    initiatorPhone = currentUser.phone,
                    initiatorRole = UserRole.FLEET_OWNER,
                    targetUid = cargo.businessOwnerUid,
                    targetName = cargo.businessOwnerName,
                    targetRole = UserRole.BUSINESS_OWNER,
                    cargoId = cargoId,
                    message = message,
                    offeredPrice = offeredPrice,
                    goodsWeightTons = cargo.weightTons
                )

                repo.sendInterest(interest)
                showSnackbar("${getString(R.string.interest_sent)} (Weight: ${cargo.weightTons}T)")
            } catch (e: Exception) {
                showSnackbar(e.message ?: getString(R.string.error_loading))
            }
        }
    }

    private fun dialPhone(phone: String) {
        startActivity(Intent(Intent.ACTION_DIAL, Uri.parse("tel:$phone")))
    }

    private fun showSnackbar(msg: String) {
        Snackbar.make(binding.root, msg, Snackbar.LENGTH_LONG).show()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.freightconnect.network

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Intent
import android.os.Build
import androidx.core.app.NotificationCompat
import com.freightconnect.R
import com.freightconnect.repository.FreightRepository
import com.freightconnect.ui.activities.MainActivity
import com.google.firebase.messaging.FirebaseMessagingService
import com.google.firebase.messaging.RemoteMessage
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch

class FCMService : FirebaseMessagingService() {

    companion object {
        const val CHANNEL_ID = "freight_notifications"
        const val CHANNEL_NAME = "Freight Notifications"
    }

    private val repo = FreightRepository()

    override fun onNewToken(token: String) {
        super.onNewToken(token)
        // Save token to Firestore
        CoroutineScope(Dispatchers.IO).launch {
            try {
                val uid = repo.currentUid()
                if (uid.isNotEmpty()) {
                    repo.updateFCMToken(uid, token)
                }
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
    }

    override fun onMessageReceived(message: RemoteMessage) {
        super.onMessageReceived(message)
        val title = message.notification?.title ?: message.data["title"] ?: "FreightConnect"
        val body = message.notification?.body ?: message.data["body"] ?: ""
        showNotification(title, body)
    }

    private fun showNotification(title: String, body: String) {
        createChannel()

        val intent = Intent(this, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
        }
        val pendingIntent = PendingIntent.getActivity(
            this, 0, intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val notification = NotificationCompat.Builder(this, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_truck_logo)
            .setContentTitle(title)
            .setContentText(body)
            .setAutoCancel(true)
            .setContentIntent(pendingIntent)
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .build()

        (getSystemService(NOTIFICATION_SERVICE) as NotificationManager)
            .notify(System.currentTimeMillis().toInt(), notification)
    }

    private fun createChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(
                CHANNEL_ID,
                CHANNEL_NAME,
                NotificationManager.IMPORTANCE_HIGH
            )
            (getSystemService(NOTIFICATION_SERVICE) as NotificationManager)
                .createNotificationChannel(channel)
        }
    }
}

package com.freightconnect.network

import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Intent
import android.os.Build
import androidx.core.app.NotificationCompat
import com.freightconnect.R
import com.freightconnect.repository.FreightRepository
import com.freightconnect.ui.activities.MainActivity
import com.google.firebase.messaging.FirebaseMessagingService
import com.google.firebase.messaging.RemoteMessage
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch

/**
 * Task 12: FCMService - Handle push notifications from Firebase Cloud Messaging
 * 
 * Handles:
 * - Interest received notifications
 * - Interest accepted/rejected notifications
 * - Cargo/route status updates
 * - FCM token management
 */
class FCMService : FirebaseMessagingService() {

    companion object {
        const val CHANNEL_ID = "freight_notifications"
        const val CHANNEL_NAME = "Freight Notifications"
        const val CHANNEL_ID_HIGH = "freight_notifications_high"
        const val CHANNEL_NAME_HIGH = "Freight Alerts"
    }

    private val repo = FreightRepository()

    override fun onNewToken(token: String) {
        super.onNewToken(token)
        // Save token to Firestore for sending notifications
        CoroutineScope(Dispatchers.IO).launch {
            try {
                val uid = repo.currentUid()
                if (uid.isNotEmpty()) {
                    repo.updateFCMToken(uid, token)
                }
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
    }

    override fun onMessageReceived(message: RemoteMessage) {
        super.onMessageReceived(message)

        val title = message.notification?.title ?: message.data["title"] ?: "FreightConnect"
        val body = message.notification?.body ?: message.data["body"] ?: ""
        val notificationType = message.data["type"] ?: "GENERAL"

        // Task 12: Route notification based on type
        when (notificationType) {
            "INTEREST_RECEIVED" -> {
                showNotificationHighPriority(title, body, " New Interest!")
            }
            "INTEREST_ACCEPTED" -> {
                showNotificationHighPriority(title, body, "✅ Interest Accepted!")
            }
            "INTEREST_REJECTED" -> {
                showNotification(title, body)
            }
            "ROUTE_BOOKED" -> {
                showNotificationHighPriority(title, body, " Route Booked!")
            }
            "CARGO_BOOKED" -> {
                showNotificationHighPriority(title, body, " Cargo Booked!")
            }
            else -> {
                showNotification(title, body)
            }
        }
    }

    /**
     * Show high-priority notification (interest/booking updates)
     */
    private fun showNotificationHighPriority(title: String, body: String, prefix: String = "") {
        createChannel()

        val intent = Intent(this, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
            // Optional: Add deep link to interests fragment
            putExtra("navigate_to", "interests")
        }

        val pendingIntent = PendingIntent.getActivity(
            this, System.currentTimeMillis().toInt(), intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val notification = NotificationCompat.Builder(this, CHANNEL_ID_HIGH)
            .setSmallIcon(R.drawable.ic_truck_logo)
            .setContentTitle("$prefix $title")
            .setContentText(body)
            .setStyle(NotificationCompat.BigTextStyle().bigText(body))
            .setAutoCancel(true)
            .setContentIntent(pendingIntent)
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .setVibrate(longArrayOf(0, 500))
            .setSound(android.provider.Settings.System.DEFAULT_NOTIFICATION_URI)
            .build()

        (getSystemService(NOTIFICATION_SERVICE) as NotificationManager)
            .notify(System.currentTimeMillis().toInt(), notification)
    }

    /**
     * Show standard notification
     */
    private fun showNotification(title: String, body: String) {
        createChannel()

        val intent = Intent(this, MainActivity::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
        }

        val pendingIntent = PendingIntent.getActivity(
            this, System.currentTimeMillis().toInt(), intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        val notification = NotificationCompat.Builder(this, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_truck_logo)
            .setContentTitle(title)
            .setContentText(body)
            .setStyle(NotificationCompat.BigTextStyle().bigText(body))
            .setAutoCancel(true)
            .setContentIntent(pendingIntent)
            .setPriority(NotificationCompat.PRIORITY_DEFAULT)
            .build()

        (getSystemService(NOTIFICATION_SERVICE) as NotificationManager)
            .notify(System.currentTimeMillis().toInt(), notification)
    }

    private fun createChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            // Standard channel
            val channel = NotificationChannel(
                CHANNEL_ID,
                CHANNEL_NAME,
                NotificationManager.IMPORTANCE_DEFAULT
            )

            // High priority channel for alerts
            val channelHigh = NotificationChannel(
                CHANNEL_ID_HIGH,
                CHANNEL_NAME_HIGH,
                NotificationManager.IMPORTANCE_HIGH
            ).apply {
                enableVibration(true)
                enableLights(true)
            }

            val manager = getSystemService(NOTIFICATION_SERVICE) as NotificationManager
            manager.createNotificationChannel(channel)
            manager.createNotificationChannel(channelHigh)
        }
    }
}

package com.freightconnect.ui.fragments

import android.os.Bundle
import android.view.*
import androidx.fragment.app.Fragment
import androidx.fragment.app.viewModels
import androidx.navigation.fragment.findNavController
import androidx.recyclerview.widget.LinearLayoutManager
import com.freightconnect.R
import com.freightconnect.databinding.FragmentFleetHomeBinding
import com.freightconnect.ui.adapters.RouteAdapter
import com.freightconnect.viewmodel.FleetHomeViewModel

class FleetHomeFragment : Fragment() {

    private var _binding: FragmentFleetHomeBinding? = null
    private val binding get() = _binding!!
    private val viewModel: FleetHomeViewModel by viewModels()
    private lateinit var routeAdapter: RouteAdapter

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        _binding = FragmentFleetHomeBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        setupRecyclerView()
        setupFab()
        observeData()
    }

    override fun onResume() {
        super.onResume()
        // Refresh data when coming back from posting a route
        viewModel.refreshData()
    }

    private fun setupRecyclerView() {
        routeAdapter = RouteAdapter(
            onRouteClick = { route ->
                val action = FleetHomeFragmentDirections.actionHomeToRouteDetail(route.routeId)
                findNavController().navigate(action)
            }
        )

        binding.rvRoutes.apply {
            adapter = routeAdapter
            layoutManager = LinearLayoutManager(requireContext())
        }

        binding.swipeRefresh.setOnRefreshListener {
            viewModel.refreshData()
        }

        // Cache views from dashboard layout
        val tvCompletedTrips = binding.root.findViewById<android.widget.TextView>(R.id.tvCompletedTrips)
        val tvTotalRoutes = binding.root.findViewById<android.widget.TextView>(R.id.tvTotalRoutes)

        // Store for use in observeData
        binding.root.tag = mapOf(
            "tvCompletedTrips" to tvCompletedTrips,
            "tvTotalRoutes" to tvTotalRoutes
        )
    }

    private fun setupFab() {
        binding.fabPostRoute.setOnClickListener {
            findNavController().navigate(R.id.action_home_to_postRoute)
        }
    }

    private fun observeData() {
        // Get cached views from dashboard layout
        @Suppress("UNCHECKED_CAST")
        val viewsMap = binding.root.tag as? Map<String, android.widget.TextView>
        val tvCompletedTrips = viewsMap?.get("tvCompletedTrips")
        val tvTotalRoutes = viewsMap?.get("tvTotalRoutes")

        viewModel.myRoutes.observe(viewLifecycleOwner) { routes ->
            binding.swipeRefresh.isRefreshing = false

            if (routes.isEmpty()) {
                binding.layoutEmpty.visibility = View.VISIBLE
                binding.rvRoutes.visibility = View.GONE
                binding.tvEmptyMessage.text = getString(R.string.no_routes_posted)
            } else {
                binding.layoutEmpty.visibility = View.GONE
                binding.rvRoutes.visibility = View.VISIBLE
                routeAdapter.submitList(routes)
            }
        }

        viewModel.receivedInterests.observe(viewLifecycleOwner) { interests ->
            if (interests.isNotEmpty()) {
                binding.badgeInterests.visibility = View.VISIBLE
                binding.badgeInterests.text = interests.size.toString()
            } else {
                binding.badgeInterests.visibility = View.GONE
            }
        }

        viewModel.isLoading.observe(viewLifecycleOwner) { loading ->
            if (loading) {
                binding.shimmerLayout.visibility = View.VISIBLE
                binding.shimmerLayout.startShimmer()
                binding.rvRoutes.visibility = View.GONE
            } else {
                binding.shimmerLayout.stopShimmer()
                binding.shimmerLayout.visibility = View.GONE
            }
        }

        // Dashboard metrics
        viewModel.completedTrips.observe(viewLifecycleOwner) { count ->
            tvCompletedTrips?.text = count.toString()
        }

        viewModel.totalPostedRoutes.observe(viewLifecycleOwner) { count ->
            tvTotalRoutes?.text = count.toString()
        }
    }


    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

