suspend fun acceptInterest(interestId: String) {

    val interest = interestsRef.document(interestId)
        .get()
        .await()
        .toObject(BookingInterest::class.java) ?: return

    // ✅ STEP 1: Fetch cargo/route and pending interests BEFORE transaction
    val cargo = if (interest.cargoId.isNotBlank()) {
        cargoRequestsRef.document(interest.cargoId).get().await()
            .toObject(CargoRequest::class.java)
    } else null

    val route = if (interest.routeId.isNotBlank()) {
        truckRoutesRef.document(interest.routeId).get().await()
            .toObject(TruckRoute::class.java)
    } else null

    val query = if (interest.cargoId.isNotBlank()) {
        interestsRef.whereEqualTo("cargoId", interest.cargoId)
    } else {
        interestsRef.whereEqualTo("routeId", interest.routeId)
    }

    val pendingDocs = query
        .whereEqualTo("status", InterestStatus.PENDING.name)
        .get()
        .await()
        .documents

    // ✅ STEP 2: Calculate new weight and status
    val cargoWeight = cargo?.weightTons ?: 0f
    val newBookedWeight = (route?.bookedWeightTons ?: 0f) + cargoWeight
    val totalCapacity = route?.availableCapacityTons ?: 0f
    val remainingCapacity = (totalCapacity - newBookedWeight).coerceAtLeast(0f)

    // Determine new route status
    val newRouteStatus = when {
        remainingCapacity <= 0f -> RouteStatus.BOOKED
        remainingCapacity < totalCapacity -> RouteStatus.PARTIALLY_BOOKED
        else -> RouteStatus.ACTIVE
    }

    // ✅ STEP 3: Run transaction (NO await inside)
    db.runTransaction { transaction ->

        // Accept selected interest
        transaction.update(
            interestsRef.document(interestId),
            "status", InterestStatus.ACCEPTED.name
        )

        // Update cargo
        if (interest.cargoId.isNotBlank() && cargo != null) {
            transaction.update(
                cargoRequestsRef.document(interest.cargoId),
                mapOf(
                    "status" to CargoStatus.BOOKED.name,
                    "assignedFleetOwnerUid" to interest.initiatorUid,
                    "assignedRouteId" to interest.routeId
                )
            )
        }

        // Update route with new booked weight and status
        if (interest.routeId.isNotBlank() && route != null) {
            transaction.update(
                truckRoutesRef.document(interest.routeId),
                mapOf(
                    "bookedWeightTons" to newBookedWeight,
                    "status" to newRouteStatus.name,
                    "bookedByUid" to interest.initiatorUid
                )
            )
        }

        // Reject all other pending interests for the same cargo/route
        pendingDocs.forEach { doc ->
            if (doc.id != interestId) {
                transaction.update(
                    doc.reference,
                    "status",
                    InterestStatus.REJECTED.name
                )
            }
        }
    }.await()

    // Task 12: Send notification to initiator that interest was accepted
    val initiator = getUser(interest.initiatorUid)
    notifyInterestAccepted(interest, initiator)
}

    suspend fun rejectInterest(interestId: String, reason: String = "") {
        // Task 10: Save rejection reason along with status
        interestsRef.document(interestId)
            .update(mapOf(
                "status" to InterestStatus.REJECTED.name,
                "rejectionReason" to reason
            )).await()

        // Task 12: Send notification to initiator that interest was rejected
        val interest = interestsRef.document(interestId).get().await()
            .toObject(BookingInterest::class.java)
        if (interest != null) {
            val initiator = getUser(interest.initiatorUid)
            notifyInterestRejected(interest, initiator)
        }
    }


    fun listenToFleetRoutes(
        uid: String,
        onUpdate: (List<TruckRoute>) -> Unit,
        onError: (Exception) -> Unit = {}
    ): ListenerRegistration =
        truckRoutesRef.whereEqualTo("fleetOwnerUid", uid)
            .orderBy("createdAt", Query.Direction.DESCENDING)
            .addSnapshotListener { snapshot, error ->
                if (error != null) {
                    onError(error)
                    return@addSnapshotListener
                }
                if (snapshot != null) {
                    val routes = snapshot.toObjects(TruckRoute::class.java)
                    onUpdate(routes)
                }
            }

    fun listenToFleetInterests(
        uid: String,
        onUpdate: (List<BookingInterest>) -> Unit,
        onError: (Exception) -> Unit = {}
    ): ListenerRegistration =
        interestsRef.whereEqualTo("targetUid", uid)
            .whereEqualTo("status", InterestStatus.PENDING.name)
            .orderBy("createdAt", Query.Direction.DESCENDING)
            .addSnapshotListener { snapshot, error ->
                if (error != null) {
                    onError(error)
                    return@addSnapshotListener
                }
                if (snapshot != null) {
                    val interests = snapshot.toObjects(BookingInterest::class.java)
                    onUpdate(interests)
                }
            }

    fun listenToBusinessCargos(
        uid: String,
        onUpdate: (List<CargoRequest>) -> Unit,
        onError: (Exception) -> Unit = {}
    ): ListenerRegistration =
        cargoRequestsRef.whereEqualTo("businessOwnerUid", uid)
            .orderBy("createdAt", Query.Direction.DESCENDING)
            .addSnapshotListener { snapshot, error ->
                if (error != null) {
                    onError(error)
                    return@addSnapshotListener
                }
                if (snapshot != null) {
                    val cargos = snapshot.toObjects(CargoRequest::class.java)
                    onUpdate(cargos)
                }
            }

    fun listenToBusinessInterests(
        uid: String,
        onUpdate: (List<BookingInterest>) -> Unit,
        onError: (Exception) -> Unit = {}
    ): ListenerRegistration =
        interestsRef.whereEqualTo("targetUid", uid)
            .orderBy("createdAt", Query.Direction.DESCENDING)
            .addSnapshotListener { snapshot, error ->
                if (error != null) {
                    onError(error)
                    return@addSnapshotListener
                }
                if (snapshot != null) {
                    val interests = snapshot.toObjects(BookingInterest::class.java)
                    onUpdate(interests)
                }
            }

    suspend fun getFleetProfile(uid: String): FleetOwnerProfile? =
        fleetProfilesRef.document(uid).get().await()
            .toObject(FleetOwnerProfile::class.java)

    suspend fun createOrUpdateFleetProfile(profile: FleetOwnerProfile) {
        fleetProfilesRef.document(profile.uid).set(profile).await()
    }

    suspend fun updateFleetStats(
        uid: String,
        completedTrip: Boolean,
        onTime: Boolean,
        rating: Float
    ) {
        fleetProfilesRef.document(uid).update(
            mapOf(
                "totalTrips" to FieldValue.increment(1),
                "completedTrips" to if (completedTrip) FieldValue.increment(1) else FieldValue.increment(0),
                "onTimeDeliveries" to if (onTime) FieldValue.increment(1) else FieldValue.increment(0),
                "ratingsSum" to FieldValue.increment(rating.toDouble()),
                "ratingsCount" to FieldValue.increment(1)
            )
        ).await()
    }

    // ═══════════════════════════════════════════════════════════════════════
    // TASK 11: REAL-TIME LISTENERS FOR INTERESTS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * Task 11: Listen to received interests in real-time (replaces polling)
     * Emits updates whenever received interests change
     */
    fun listenToReceivedInterests(
        uid: String,
        onUpdate: (List<BookingInterest>) -> Unit,
        onError: (Exception) -> Unit = {}
    ): ListenerRegistration =
        interestsRef.whereEqualTo("targetUid", uid)
            .orderBy("createdAt", Query.Direction.DESCENDING)
            .addSnapshotListener { snapshot, error ->
                if (error != null) {
                    onError(error)
                    return@addSnapshotListener
                }
                if (snapshot != null) {
                    val interests = snapshot.toObjects(BookingInterest::class.java)
                    onUpdate(interests)
                }
            }

    /**
     * Task 11: Listen to sent interests in real-time (replaces polling)
     * Emits updates whenever sent interests change
     */
    fun listenToSentInterests(
        uid: String,
        onUpdate: (List<BookingInterest>) -> Unit,
        onError: (Exception) -> Unit = {}
    ): ListenerRegistration =
        interestsRef.whereEqualTo("initiatorUid", uid)
            .orderBy("createdAt", Query.Direction.DESCENDING)
            .addSnapshotListener { snapshot, error ->
                if (error != null) {
                    onError(error)
                    return@addSnapshotListener
                }
                if (snapshot != null) {
                    val interests = snapshot.toObjects(BookingInterest::class.java)
                    onUpdate(interests)
                }
            }

    /**
     * Task 11: Get unread interest count (pending interests received)
     * Used for badge counter
     */
    suspend fun getUnreadInterestCount(uid: String): Int {
        return try {
            interestsRef.whereEqualTo("targetUid", uid)
                .whereEqualTo("status", InterestStatus.PENDING.name)
                .get().await()
                .size()
        } catch (e: Exception) {
            0
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // NOTIFICATIONS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * Task 12: Create and send a notification to user
     * Called when interest is received, accepted, rejected, etc
     */
    suspend fun sendNotification(
        recipientUid: String,
        type: NotificationType,
        title: String,
        body: String,
        relatedRouteId: String = "",
        relatedCargoId: String = "",
        relatedInterestId: String = ""
    ) {
        val notification = notifications(
            recipientUid = recipientUid,
            type = type,
            title = title,
            body = body,
            relatedRouteId = relatedRouteId,
            relatedCargoId = relatedCargoId,
            relatedInterestId = relatedInterestId
        )
        createNotification(notification)
    }

    /**
     * Task 12: Notify recipient when interest is received
     */
    suspend fun notifyInterestReceived(
        interest: BookingInterest,
        recipientUser: User?
    ) {
        if (recipientUser?.fcmToken?.isNotBlank() == true) {
            sendNotification(
                recipientUid = interest.targetUid,
                type = NotificationType.INTEREST_RECEIVED,
                title = "New interest from ${interest.initiatorName}",
                body = "${interest.initiatorRole.name.replace("_", " ")} is interested in your ${if (interest.cargoId.isNotBlank()) "cargo" else "route"}!",
                relatedInterestId = interest.interestId,
                relatedCargoId = interest.cargoId,
                relatedRouteId = interest.routeId
            )
        }
    }

    /**
     * Task 12: Notify initiator when interest is accepted
     */
    suspend fun notifyInterestAccepted(
        interest: BookingInterest,
        initiatorUser: User?
    ) {
        if (initiatorUser?.fcmToken?.isNotBlank() == true) {
            sendNotification(
                recipientUid = interest.initiatorUid,
                type = NotificationType.INTEREST_ACCEPTED,
                title = "Interest accepted!",
                body = "${interest.targetName} accepted your interest. You can now contact them!",
                relatedInterestId = interest.interestId,
                relatedCargoId = interest.cargoId,
                relatedRouteId = interest.routeId
            )
        }
    }

    /**
     * Task 12: Notify initiator when interest is rejected
     */
    suspend fun notifyInterestRejected(
        interest: BookingInterest,
        initiatorUser: User?
    ) {
        if (initiatorUser?.fcmToken?.isNotBlank() == true) {
            sendNotification(
                recipientUid = interest.initiatorUid,
                type = NotificationType.INTEREST_REJECTED,
                title = "Interest declined",
                body = "${interest.targetName} declined your interest${if (interest.rejectionReason.isNotBlank()) ": ${interest.rejectionReason}" else ""}",
                relatedInterestId = interest.interestId
            )
        }
    }

    suspend fun createNotification(notification: notifications) {
        val ref = notificationsRef.document()
        notificationsRef.document(ref.id).set(notification.copy(id = ref.id)).await()
    }

    suspend fun getUserNotifications(uid: String): List<notifications> =
        notificationsRef.whereEqualTo("recipientUid", uid)
            .orderBy("createdAt", Query.Direction.DESCENDING)
            .limit(50)
            .get().await()
            .toObjects(notifications::class.java)

    suspend fun markNotificationAsRead(notificationId: String) {
        notificationsRef.document(notificationId).update("isRead", true).await()
    }
}

package com.freightconnect.ui.adapters

import android.content.Context
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.core.content.ContextCompat
import androidx.recyclerview.widget.DiffUtil
import androidx.recyclerview.widget.ListAdapter
import androidx.recyclerview.widget.RecyclerView
import com.freightconnect.R
import com.freightconnect.databinding.ItemInterestCardBinding
import com.freightconnect.model.BookingInterest
import com.freightconnect.model.InterestStatus
import com.freightconnect.repository.FreightRepository
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import java.text.SimpleDateFormat
import java.util.*

class InterestAdapter(
    private val onAccept: (BookingInterest) -> Unit,
    private val onReject: (BookingInterest, String) -> Unit,  // Task 10: Added reason parameter
    private val onCall: (String) -> Unit,
    private val context: Context? = null
) : ListAdapter<BookingInterest, InterestAdapter.InterestViewHolder>(InterestDiffCallback()) {

    private val repo = FreightRepository()

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): InterestViewHolder {
        val binding = ItemInterestCardBinding.inflate(
            LayoutInflater.from(parent.context), parent, false
        )
        return InterestViewHolder(binding)
    }

    override fun onBindViewHolder(holder: InterestViewHolder, position: Int) {
        holder.bind(getItem(position))
    }

    inner class InterestViewHolder(
        private val binding: ItemInterestCardBinding
    ) : RecyclerView.ViewHolder(binding.root) {

        fun bind(interest: BookingInterest) {
            binding.apply {
                // Basic info
                tvInitiatorName.text = interest.initiatorName
                tvInitiatorRole.text = interest.initiatorRole.name.replace("_", " ")
                tvMessage.text = interest.message.ifBlank { "No message" }
                tvOfferedPrice.text = if (interest.offeredPrice > 0) 
                    "Offered: ₹${interest.offeredPrice.toLong()}" 
                else "Price: Negotiable"
                tvCreatedAt.text = SimpleDateFormat("dd MMM, hh:mm a", Locale.getDefault())
                    .format(Date(interest.createdAt))

                // Set direction indicator (Task 2)
                setDirectionIndicator(interest)

                // Status badge
                val (statusColor, statusText) = when (interest.status) {
                    InterestStatus.PENDING -> Pair(R.color.status_pending, "Pending")
                    InterestStatus.ACCEPTED -> Pair(R.color.status_booked, "Accepted")
                    InterestStatus.REJECTED -> Pair(R.color.status_cancelled, "Rejected")
                    InterestStatus.WITHDRAWN -> Pair(R.color.status_cancelled, "Withdrawn")
                }
                tvStatus.text = statusText
                tvStatus.setBackgroundResource(statusColor)

                // Load interest context: cargo/route details (Task 3)
                loadInterestContext(interest)

                // Show action buttons only for pending interests
                if (interest.status == InterestStatus.PENDING) {
                    layoutActions.visibility = View.VISIBLE
                    btnAccept.setOnClickListener { onAccept(interest) }
                    btnReject.setOnClickListener { onReject(interest, "") }  // Task 10: Pass reason
                } else {
                    layoutActions.visibility = View.GONE
                }

                // Show call button for accepted interests
                if (interest.status == InterestStatus.ACCEPTED) {
                    btnCall.visibility = View.VISIBLE
                    btnCall.setOnClickListener { onCall(interest.initiatorPhone) }
                } else {
                    btnCall.visibility = View.GONE
                }
            }
        }

        private fun setDirectionIndicator(interest: BookingInterest) {
            val currentUid = repo.currentUid()
            val isIncoming = currentUid == interest.targetUid

            binding.apply {
                if (isIncoming) {
                    // Incoming: left arrow, blue color
                    ivDirection.setImageResource(R.drawable.ic_arrow_forward)
                    ivDirection.rotation = 180f
                    ivDirection.setColorFilter(ContextCompat.getColor(root.context, R.color.color_info), android.graphics.PorterDuff.Mode.SRC_IN)
                    tvDirection.text = root.context.getString(R.string.direction_incoming)
                    tvDirection.setTextColor(ContextCompat.getColor(root.context, R.color.color_info))
                } else {
                    // Outgoing: right arrow, green color
                    ivDirection.setImageResource(R.drawable.ic_arrow_forward)
                    ivDirection.rotation = 0f
                    ivDirection.setColorFilter(ContextCompat.getColor(root.context, R.color.color_success), android.graphics.PorterDuff.Mode.SRC_IN)
                    tvDirection.text = root.context.getString(R.string.direction_outgoing)
                    tvDirection.setTextColor(ContextCompat.getColor(root.context, R.color.color_success))
                }
            }
        }

        private fun loadInterestContext(interest: BookingInterest) {
            binding.apply {
                // Load in coroutine
                CoroutineScope(Dispatchers.Main).launch {
                    try {
                        if (interest.cargoId.isNotBlank()) {
                            // Load cargo details
                            val cargo = repo.getCargoRequest(interest.cargoId)
                            if (cargo != null) {
                                tvContextLocation.text = "${cargo.pickupCity} → ${cargo.deliveryCity}"
                                tvContextWeight.text = "${cargo.weightTons} tons"
                                tvContextDate.text = SimpleDateFormat("dd MMM yyyy", Locale.getDefault())
                                    .format(Date(cargo.pickupDate))
                                cardContext.visibility = View.VISIBLE
                            } else {
                                cardContext.visibility = View.GONE
                            }
                        } else if (interest.routeId.isNotBlank()) {
                            // Load route details
                            val route = repo.getTruckRoute(interest.routeId)
                            if (route != null) {
                                tvContextLocation.text = "${route.fromCity} → ${route.toCity}"
                                tvContextWeight.text = "${route.availableCapacityTons} tons"
                                tvContextDate.text = SimpleDateFormat("dd MMM yyyy", Locale.getDefault())
                                    .format(Date(route.departureDate))
                                cardContext.visibility = View.VISIBLE
                            } else {
                                cardContext.visibility = View.GONE
                            }
                        } else {
                            cardContext.visibility = View.GONE
                        }
                    } catch (e: Exception) {
                        cardContext.visibility = View.GONE
                        e.printStackTrace()
                    }
                }
            }
        }
    }

    private class InterestDiffCallback : DiffUtil.ItemCallback<BookingInterest>() {
        override fun areItemsTheSame(oldItem: BookingInterest, newItem: BookingInterest) =
            oldItem.interestId == newItem.interestId

        override fun areContentsTheSame(oldItem: BookingInterest, newItem: BookingInterest) =
            oldItem == newItem
    }
}

