                tvTotalCapacity.text = "Total: ${route.availableCapacityTons}T"

                // Calculate progress percentage (0-100)
                val progressPercent = if (route.availableCapacityTons > 0) {
                    ((route.bookedWeightTons / route.availableCapacityTons) * 100).toInt()
                        .coerceIn(0, 100)
                } else {
                    0
