            try {
                val vehicle = Vehicle(
                    fleetOwnerUid = currentUid,
                    vehicleNumber = vehicleNumber,
                    vehicleType = vehicleType,
                    totalCapacityTons = totalCapacity,
                    currentAvailabilityTons = totalCapacity,
                    isActive = true
