                _error.value = "Failed to add vehicle: ${e.message}"
                _postSuccess.value = false
            } finally {
                _isLoading.value = false
            }
        }
    }

    fun updateVehicle(
        vehicleId: String,
        vehicleNumber: String,
        vehicleType: VehicleType,
        totalCapacity: Float,
        isActive: Boolean
    ) {
        if (vehicleNumber.isBlank()) {
            _error.value = "Vehicle number is required"
            return
        }
        if (totalCapacity <= 0) {
            _error.value = "Vehicle capacity must be greater than 0"
            return
        }

        _isLoading.value = true
        viewModelScope.launch {
            try {
                val currentVehicle = repo.getVehicle(vehicleId) ?: return@launch
                val updated = currentVehicle.copy(
                    vehicleNumber = vehicleNumber,
                    vehicleType = vehicleType,
                    totalCapacityTons = totalCapacity,
