rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isSignedIn() {
      return request.auth != null;
    }

    match /users/{userId} {
      allow read, write: if isSignedIn() && request.auth.uid == userId;
    }

    match /truckRoutes/{routeId} {
      allow read: if isSignedIn();
      allow create: if isSignedIn();
      allow update: if isSignedIn() && request.auth.uid == resource.data.fleetOwnerUid;
    }

    match /cargoRequests/{cargoId} {
      allow read: if isSignedIn();
      allow create: if isSignedIn();
      allow update: if isSignedIn() && request.auth.uid == resource.data.businessOwnerUid;
    }

    match /bookingInterests/{interestId} {
      allow read: if isSignedIn() &&
        (request.auth.uid == resource.data.targetUid || request.auth.uid == resource.data.initiatorUid);
      allow create: if isSignedIn();
      allow update: if isSignedIn() && request.auth.uid == resource.data.targetUid;
    }

    match /notifications/{notificationId} {
      allow read: if isSignedIn() && request.auth.uid == resource.data.recipientUid;
      allow create: if isSignedIn();
      allow update: if isSignedIn() && request.auth.uid == resource.data.recipientUid;
    }

    match /{document=**} {
      allow read, write: if false;
    }
  }
}

rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isSignedIn() {
      return request.auth != null;
    }

    match /users/{userId} {
      allow read, write: if isSignedIn() && request.auth.uid == userId;
    }

    match /truckRoutes/{routeId} {
      allow read: if isSignedIn();
      allow create: if isSignedIn() && request.auth.uid == request.resource.data.fleetOwnerUid;
      allow update: if isSignedIn() && (
        request.auth.uid == resource.data.fleetOwnerUid ||
        request.resource.data.diff(resource.data).changedKeys()
          .hasOnly(["bookedWeightTons", "status", "bookedByUid"])
      );
    }

    match /cargoRequests/{cargoId} {
      allow read: if isSignedIn();
      allow create: if isSignedIn() && request.auth.uid == request.resource.data.businessOwnerUid;
      allow update: if isSignedIn() && (
        request.auth.uid == resource.data.businessOwnerUid ||
        request.resource.data.diff(resource.data).changedKeys()
          .hasOnly(["status", "assignedFleetOwnerUid", "assignedRouteId"])
      );
    }

    match /bookingInterests/{interestId} {
      allow read: if isSignedIn() &&
        (request.auth.uid == resource.data.targetUid || request.auth.uid == resource.data.initiatorUid);
      allow create: if isSignedIn();
      allow update: if isSignedIn() && request.auth.uid == resource.data.targetUid;
    }

    match /notifications/{notificationId} {
      allow read: if isSignedIn() && request.auth.uid == resource.data.recipientUid;
      allow create: if isSignedIn();
      allow update: if isSignedIn() && request.auth.uid == resource.data.recipientUid;
    }

    match /{document=**} {
      allow read, write: if false;
    }
  }
}
